import { candidateAsset, exampleProvenance, referenceAsset } from '#shared/studio/example'
import type { CandidateReview } from '#shared/studio/contracts'

export function downloadEvidence(review: CandidateReview | null) {
  const evidence = {
    schemaVersion: 'product-studio.example.v1',
    generatedAt: new Date().toISOString(),
    reference: referenceAsset,
    candidate: candidateAsset,
    provenance: exampleProvenance,
    review,
    authority: 'browser-only-attestation',
    disclaimer:
      'This saved public example was not generated by your account. A local review is not a server authorization, legal clearance, or automatic consistency score.',
  }
  const url = URL.createObjectURL(
    new Blob([JSON.stringify(evidence, null, 2)], { type: 'application/json' }),
  )
  const anchor = document.createElement('a')
  anchor.href = url
  anchor.download = 'product-studio-evidence.json'
  anchor.click()
  setTimeout(() => URL.revokeObjectURL(url), 1000)
}
